"""Cached price lookups."""
import threading

TABLE = {("A", "USD"): 10.0, ("A", "EUR"): 9.0, ("B", "USD"): 4.0, ("B", "EUR"): 3.5}
_cache = {}
_lock = threading.Lock()


def lookup(sku, currency):
    return TABLE[(sku, currency)]


def cached_price(sku, currency):
    with _lock:
        if sku in _cache:
            return _cache[sku]
        value = lookup(sku, currency)
        _cache[sku] = value
        return value
